REL = {"best_effort": 0, "reliable": 1}
DUR = {"volatile": 0, "transient_local": 1}

def match(pub, sub):
    ok_rel = REL[pub["reliability"]] >= REL[sub["reliability"]]
    ok_dur = DUR[pub["durability"]] >= DUR[sub["durability"]]
    return ok_rel and ok_dur

sensor_pub = {"reliability": "best_effort", "durability": "volatile"}
door_pub = {"reliability": "reliable", "durability": "transient_local"}
recorder = {"reliability": "reliable", "durability": "volatile"}
tolerant = {"reliability": "best_effort", "durability": "volatile"}
print("센서 → 녹화기(reliable):", match(sensor_pub, recorder))
print("센서 → 녹화기(best_effort):", match(sensor_pub, tolerant))
print("문 상태 → 녹화기:", match(door_pub, recorder))
# 센서 → 녹화기(reliable): False
# 센서 → 녹화기(best_effort): True
# 문 상태 → 녹화기: True
